/**
 * O que é GERADO dentro do pacote — o que difere de um workspace de deploy do repositório.
 *
 * O `firebase.json` do repositório não serve como está por duas razões: o `predeploy` dele compila o
 * kernel (que no pacote já vem compilado, e cujo `src/` não viaja), e o hosting dele aponta para
 * `dist`. Aqui o `predeploy` compila SÓ o que o escritório escreveu.
 */

export interface RepoFunctionsPackage {
  dependencies?: Record<string, string>;
  devDependencies?: Record<string, string>;
  engines?: Record<string, string>;
}

export interface HostingConfig {
  ignore: string[];
  rewrites: unknown[];
  headers: unknown[];
}

export const packageFirebaseJson = (hosting: HostingConfig): string => JSON.stringify({
  firestore: {
    rules: 'firestore.rules',
    indexes: 'firestore.indexes.json',
  },
  storage: {
    rules: 'storage.rules',
  },
  functions: {
    source: 'functions',
    predeploy: ['npm --prefix "$RESOURCE_DIR" run build'],
  },
  hosting: {
    public: 'hosting',
    ignore: hosting.ignore,
    rewrites: hosting.rewrites,
    headers: hosting.headers,
  },
}, null, 2) + '\n';

/**
 * As dependências são copiadas INTACTAS do `functions/package.json` do repositório, para que o
 * `package-lock.json` que viaja junto continue válido. O que muda é só o entrypoint (passa a ser o
 * `index.js` que soma kernel e custom) e o `build`, que agora compila apenas `custom/`.
 */
/**
 * A `version` não é enfeite: sem ela o npm não consegue formar `nome@versão` e todo aviso dele sobre
 * este pacote sai com `package: undefined`, o que faz parecer que o arquivo está corrompido.
 *
 * `engines.node` vem do repositório e descreve o RUNTIME das Cloud Functions — é por ele que o Firebase
 * escolhe em qual Node a function roda. Ele não descreve a máquina de quem instala, e é por isso que o
 * npm avisa `EBADENGINE` quando as duas versões diferem: o aviso é esperado e não impede nada. Trocar
 * o valor por uma faixa (`>=22`) calaria o aviso e passaria a deixar a escolha do runtime ambígua para
 * o Firebase — o preço errado pela linha de saída.
 */
export const packageFunctionsPackageJson = (
  source: RepoFunctionsPackage,
  version: string,
): string => JSON.stringify({
  name: 'microteia-functions',
  version,
  private: true,
  main: 'index.js',
  engines: source.engines ?? { node: '22' },
  scripts: {
    build: 'tsc -p custom/tsconfig.json',
  },
  dependencies: source.dependencies ?? {},
  devDependencies: source.devDependencies ?? {},
}, null, 2) + '\n';

/**
 * Entrypoint da instalação. O espalhamento mantém os nomes PLANOS (`onUserCreated`, e não
 * `kernel-onUserCreated`), que é o que os deploys por nome e os gatilhos já existentes esperam.
 */
export const packageFunctionsIndexJs = (): string => `// Generated by "microteia pack". Do not edit.
//
// The deployed function set is the compiled kernel plus whatever this installation added under
// custom/. Kernel functions cannot be overridden here: custom/ is spread last, so a name collision
// would silently replace a kernel trigger — keep your function names distinct.
const kernel = require('./lib/index.js');
const custom = require('./custom/lib/index.js');

module.exports = { ...kernel, ...custom };
`;

export const packageCustomTsconfig = (): string => JSON.stringify({
  compilerOptions: {
    module: 'commonjs',
    moduleResolution: 'node',
    target: 'es2022',
    lib: ['ES2022'],
    types: ['node'],
    rootDir: 'src',
    outDir: 'lib',
    strict: true,
    esModuleInterop: true,
    skipLibCheck: true,
    sourceMap: true,
    noImplicitReturns: true,
  },
  include: ['src'],
}, null, 2) + '\n';

export const packageCustomIndexTs = (): string => `// Cloud Functions belonging to this installation.
//
// Everything exported from this file is deployed alongside the Microteia kernel and survives a
// kernel upgrade — "microteia deploy" replaces lib/ but never touches custom/.
//
// Functions must be pinned to the same region as the rest of the installation, otherwise Firestore
// triggers will not fire. Example:
//
//   import { onCall } from 'firebase-functions/v2/https';
//
//   export const helloOffice = onCall({ region: 'southamerica-east1', cors: true }, () => {
//     return { ok: true };
//   });

export {};
`;

/**
 * O Console empacotado para rodar FORA do repositório. O `type: module` não é detalhe: o compilado é
 * ESM, e sem esta declaração o Node só o carrega por adivinhação de sintaxe — que existe a partir do
 * 22.7 e falha em silêncio nas versões anteriores, com "Cannot use import statement outside a module".
 * O `bin` é o que permite `npm link` e, daí, o comando `microteia` global.
 */
export const consolePackageJson = (version: string): string => JSON.stringify({
  name: 'microteia-console',
  version,
  private: true,
  type: 'module',
  bin: { microteia: 'lib/index.js' },
  engines: { node: '>=22' },
}, null, 2) + '\n';

export const consoleReadme = (version: string): string => `# Microteia Console ${version}

Installs and updates Microteia in a Firebase project you own. This directory is self-contained: it
needs no Microteia repository and no npm dependencies.

    node lib/index.js --help

## Getting a "microteia" command

Link the entrypoint into any directory already on your PATH. It is executable and carries its own
shebang, so no npm and **no sudo** are involved:

    mkdir -p ~/.local/bin
    ln -s "$PWD/lib/index.js" ~/.local/bin/microteia
    microteia --help

\`npm link\` also works, but only where npm's global prefix belongs to your user. With Node installed
system-wide (prefix \`/usr/local\`, owned by root) it fails with EACCES, and \`sudo npm link\` — while it
does work — writes root-owned files into the global prefix, which then need sudo to remove
(\`sudo npm rm -g microteia-console\`). Pointing npm at a user-owned prefix avoids both:

    npm config set prefix ~/.npm-global
    export PATH="$HOME/.npm-global/bin:$PATH"   # add to ~/.zshrc
    npm link

## Using it

    microteia init --name "<office>"
    microteia connect --project <your-firebase-project-id>
    microteia deploy --kernel <microteia-kernel-x.y.z>.tgz

\`connect\` prints everything that has to be prepared in the Firebase project first — start with the
Blaze plan, since nothing else can be created without it.

Later, whenever an office installs an extension that needs server-side resources, run:

    microteia provision

The extension shows "Backend pending" in the application until you do, and stays out of the menu.

## What has to exist on this machine

| Tool          | Used for                                                       |
| ------------- | -------------------------------------------------------------- |
| Node.js 22+   | running this Console (newer is fine; the functions' own runtime is pinned to 22) |
| \`firebase\`    | every deploy — authenticate with \`firebase login\` first          |
| \`npm\`, \`tar\` | installing the functions' dependencies and unpacking the kernel  |
| \`gcloud\`      | creating the App Engine application, and reading which extensions an office installed (\`gcloud auth login\`) |

The kernel package itself is built from the Microteia repository (\`npm run pack:kernel\`) and handed
to you as a \`.tgz\`. The \`pack\` command in here only works inside that repository.
`;

